// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address sender) public {
        vm.assume(sender != address(0));
        uint256 amt = bound(amount, 0, 1 ether);

        vm.deal(sender, amt);

        uint256 before = c.depositsCount();

        vm.prank(sender);
        (bool ok, ) = address(c).call{value: amt}("");
        assertTrue(ok);

        assertTrue(c.depositsCount() == before + 1);
    }
}
